-- assets where type in (domain, subdomain) and discovered_at > -7d | bucket discovered_at by day
Count of assets where type is one of domain, subdomain and discovered_at is after 7 days ago, per day of discovered_at, ordered by discovered_at ascending

SELECT date_trunc('day', assets.discovered_at AT TIME ZONE 'UTC') AS c0, count(*) AS c1 FROM assets WHERE assets.tenant_id = $1 AND (assets.id IN (SELECT uaa.asset_id FROM user_accessible_assets uaa WHERE uaa.user_id = $2 AND uaa.tenant_id = $3) AND NOT EXISTS (SELECT 1 FROM assets ph WHERE ph.id = assets.id AND ph.tenant_id = $3 AND ph.program_only AND EXISTS (SELECT 1 FROM asset_program_links pl JOIN bounty_programs pp ON pp.tenant_id = pl.tenant_id AND pp.id = pl.program_id WHERE pl.tenant_id = ph.tenant_id AND pl.asset_id = ph.id AND pp.visibility = 'private') AND NOT EXISTS (SELECT 1 FROM asset_program_links pl JOIN bounty_programs pp ON pp.tenant_id = pl.tenant_id AND pp.id = pl.program_id WHERE pl.tenant_id = ph.tenant_id AND pl.asset_id = ph.id AND NOT (pp.visibility = 'private' AND NOT EXISTS ( SELECT 1 FROM groups pg JOIN group_members pgm ON pgm.group_id = pg.id WHERE pg.tenant_id = pp.tenant_id AND pg.id = pp.group_id AND pg.is_active AND pgm.user_id = $2))))) AND (((assets.asset_type = ANY($4::text[])) AND (assets.discovered_at > $5::timestamptz)) AND ((NOT COALESCE((assets.deleted_at IS NOT NULL), FALSE)) AND (NOT COALESCE((assets.program_only), FALSE)))) GROUP BY 1 ORDER BY c0 ASC NULLS LAST LIMIT 1001

args: [11111111-1111-1111-1111-111111111111 22222222-2222-2222-2222-222222222222 11111111-1111-1111-1111-111111111111 {"domain","subdomain"} 2026-10-11 12:00:00 +0000 UTC]
